import{_ as a,C as r,o as e,c as s,E as n,a2 as o}from"./chunks/framework.BOeh4kYD.js";const i="/joinwell52/assets/figures/miit-ai-sme-support-plan/zh/01-policy-sequence.png",g="/joinwell52/assets/figures/miit-ai-sme-support-plan/zh/02-one-person-company.png",l="/joinwell52/assets/figures/miit-ai-sme-support-plan/zh/03-two-sided-market.png",h="/joinwell52/assets/figures/miit-ai-sme-support-plan/zh/04-scenario-conversion.png",c="/joinwell52/assets/figures/miit-ai-sme-support-plan/zh/05-2028-targets.png",q=JSON.parse('{"title":"工信部《人工智能中小企业创业支持计划》深度解读：AI创业生态正在形成","description":"","frontmatter":{"title":"工信部《人工智能中小企业创业支持计划》深度解读：AI创业生态正在形成","date":"2026-09-08","language":"zh-CN","article_type":"policy-analysis","summary":"工信部《人工智能中小企业创业支持计划（2026—2028年）》把算力、数据、场景、开源、资本和服务保障纳入同一框架，AI创业生态正在从政策方向走向组织实施。","publication_authorized":true,"lifecycle":"Published","column":"industry-architecture","category":"daily","edition":"research-center","cover":"/assets/covers/miit-ai-sme-support-plan.png"},"headers":[],"relativePath":"zh/industry/2026-09-08-miit-ai-sme-support-plan.md","filePath":"zh/industry/2026-09-08-miit-ai-sme-support-plan.md","lastUpdated":1788836110000}'),m={name:"zh/industry/2026-09-08-miit-ai-sme-support-plan.md"};function u(d,p,A,b,f,I){const t=r("ArticleCover");return e(),s("div",null,[n(t,{image:"/assets/covers/miit-ai-sme-support-plan.png",kicker:"行业架构 · 政策解读",title:"工信部《人工智能中小企业创业支持计划》深度解读：AI创业生态正在形成",summary:"工信部《人工智能中小企业创业支持计划（2026—2028年）》把算力、数据、场景、开源、资本和服务保障纳入同一框架，AI创业生态正在从政策方向走向组织实施。",version:"2026-09-08",languageHref:"/en/industry/2026-09-08-miit-ai-sme-support-plan",languageLabel:"English"}),p[0]||(p[0]=o('<h1 id="工信部《人工智能中小企业创业支持计划》深度解读-ai创业生态正在形成" tabindex="-1">工信部《人工智能中小企业创业支持计划》深度解读：AI创业生态正在形成 <a class="header-anchor" href="#工信部《人工智能中小企业创业支持计划》深度解读-ai创业生态正在形成" aria-label="Permalink to &quot;工信部《人工智能中小企业创业支持计划》深度解读：AI创业生态正在形成&quot;">​</a></h1><p>2026 年 9 月 4 日，工业和信息化部办公厅正式发布<a href="https://www.miit.gov.cn/jgsj/qyj/wjfb/art/2026/art_86c400b4473849818629663a94a6d44b.html" target="_blank" rel="noreferrer">《人工智能中小企业创业支持计划（2026—2028年）》</a>。</p><p>文件编号为<strong>工信厅企业〔2026〕31号</strong>，成文日期为 8 月 29 日，印发对象是各省、自治区、直辖市、计划单列市及新疆生产建设兵团中小企业主管部门，要求各地“结合实际认真抓好落实”。截至 9 月 8 日，从工信部中小企业局“文件发布”栏目看，它也是目前最新发布的一项文件。</p><p>如果只把它理解成又一份“扶持人工智能企业”的政策，可能会低估它。</p><p>因为这份只有 7 页、15 项重点工作的文件，实际上回答了一个更大的问题：</p><p><strong>当人工智能从少数大模型公司的技术竞争，进入千行百业的大规模应用阶段以后，中国准备依靠谁去完成最后一公里？</strong></p><p>答案正在变得越来越清楚：</p><p>不是只靠几家大模型公司，也不是只靠大型互联网平台。</p><p>国家正在有意识地培育一大批人工智能中小企业、智能原生企业、智能体开发者、开源创业者、人工智能应用服务商，甚至“一人公司”和“超级个体”，让它们成为人工智能进入数百万家企业和真实产业场景的毛细血管。</p><p>这可能是这份文件最值得重视的地方。</p><hr><h2 id="一、先不要看补贴-要看这份文件出现在什么时间点" tabindex="-1">一、先不要看补贴，要看这份文件出现在什么时间点 <a class="header-anchor" href="#一、先不要看补贴-要看这份文件出现在什么时间点" aria-label="Permalink to &quot;一、先不要看补贴，要看这份文件出现在什么时间点&quot;">​</a></h2><p>理解一项产业政策，最重要的往往不是孤立地读里面的某一句话，而是看它出现在怎样的政策序列中。</p><p>2025 年 8 月，国务院发布《关于深入实施“人工智能＋”行动的意见》。</p><p>这份国家级文件提出，到 <strong>2027 年，新一代智能终端、智能体等应用普及率超过 70%；到 2030 年超过 90%</strong>。它讨论的已经不是“要不要发展人工智能”，而是人工智能怎样大范围进入科技、产业、消费、民生、治理等领域。</p><p>进入“十五五”以后，这条主线进一步升级。</p><p>国家“十五五”规划纲要把“人工智能＋”放进全方位推进数智技术赋能的国家发展框架，明确提出发展多模态、智能体、具身智能、群体智能，培育智能原生新模式新业态，建设国家人工智能应用中试基地，同时提出健全中小企业数智赋能服务体系和推进开源体系建设。</p><p>然后，从 2026 年春天开始，我们看到工信部的政策明显开始进入“施工阶段”。</p><p>4 月，部署普惠算力赋能中小企业，提出中国算力平台、中小企业专区、算力银行、算力超市，以及算力券、存力券、运力券等机制，解决的是<strong>中小企业用不起、接不到算力的问题</strong>。</p><p>7 月，发布新版“小快轻准”数字化产品和服务培育指引，解决的是<strong>什么样的产品适合中小企业使用</strong>——不能动辄建设大型系统，而应该更加轻量、快速、低成本、精准解决问题。</p><p>8 月 31 日，工信部发布 414 号文，开展人工智能应用服务商培育专项行动，提出到 2026 年底全国服务商资源池突破 2000 家，到 2027 年不少于 3000 家。它解决的是<strong>谁去帮助企业完成 AI 咨询、实施、运营和治理</strong>的问题。</p><p>9 月 3 日，十部门联合发布《促进中小企业发展“十五五”规划》，第一次把“人工智能＋创业、＋转型、＋管理、＋服务”放进未来五年的中小企业政策框架。</p><p>第二天，也就是 9 月 4 日，《人工智能中小企业创业支持计划（2026—2028年）》发布。</p><p>这样连起来看，逻辑就非常清楚了：</p><blockquote><p>国家顶层确定“人工智能＋” → 建算力基础设施 → 培育适合中小企业的小型 AI 产品 → 培育 AI 应用服务商 → 培育大量 AI 创业企业 → 让供给端与数以百万计的中小企业需求端发生连接。</p></blockquote><p>所以，这份最新文件不是一个孤立政策。</p><p><strong>它更像是在为中国人工智能应用产业建设“创业者供给层”。</strong></p><p><a href="/joinwell52/assets/figures/miit-ai-sme-support-plan/zh/01-policy-sequence.png"><img src="'+i+'" alt="从顶层战略到创业者供给层"></a></p><p><em>图 1｜五项政策动作从战略、基础设施、产品和交付，逐步推进到创业主体培育。点击图片可查看大图。</em></p><hr><h2 id="二、真正重要的变化-国家开始正式讨论-一人公司-和-超级个体" tabindex="-1">二、真正重要的变化：国家开始正式讨论“一人公司”和“超级个体” <a class="header-anchor" href="#二、真正重要的变化-国家开始正式讨论-一人公司-和-超级个体" aria-label="Permalink to &quot;二、真正重要的变化：国家开始正式讨论“一人公司”和“超级个体”&quot;">​</a></h2><p>整份文件中最容易被传播的一句话，可能是：</p><blockquote><p>鼓励各地对依托智能工具开展敏捷创业的“一人公司”、超级个体等微型主体给予包容支持。</p></blockquote><p>紧接着还有一句：</p><blockquote><p>加快培育“智能原生”企业，支持开源社区核心贡献者、智能体开发者等新兴群体探索商业化路径。</p></blockquote><p>这两句话看似很短，实际上非常重要。</p><p>需要先说明，它并不意味着国家创造了一个叫“一人公司”的新工商登记类别，也不能简单理解为以后个人做 AI 就能拿补贴。</p><p>它真正表达的是另一层意思：</p><p><strong>国家政策开始承认，人工智能正在改变企业形成的最小经济单位。</strong></p><p>过去，创办一家软件公司需要产品经理、程序员、设计、市场、客服、运营等一系列岗位。今天，一个熟练使用大模型、Agent、自动化工具的人，理论上可以调动过去一个小团队才能拥有的生产能力。</p><p>所以，“一人公司”真正值得关注的并不是“一人”，而是：</p><p><strong>一个人背后拥有了一支由人工智能构成的数字生产团队。</strong></p><p>这也是为什么文件没有停在“一人公司”，而是紧接着使用了三个很新的词：</p><p><strong>智能原生企业、开源社区核心贡献者、智能体开发者。</strong></p><p>这说明国家对 AI 创业主体的认识已经不再局限于传统意义上的“有办公室、有几十名员工、有完整组织架构的软件公司”。</p><p>未来有可能出现大量非常小的组织，却拥有相当高的知识生产能力、软件开发能力和服务能力。</p><p>这是 AI 带来的组织生产率变化第一次如此鲜明地进入国家中小企业创业政策。</p><p><a href="/joinwell52/assets/figures/miit-ai-sme-support-plan/zh/02-one-person-company.png"><img src="'+g+'" alt="一人公司改变企业的最小生产单位"></a></p><p><em>图 2｜“一人公司”的关键不是减少责任主体，而是让一个创业者能够调动由 AI 扩展的生产能力。</em></p><hr><h2 id="三、-智能体开发者-被单独写进去-意味着-agent-已经开始从技术概念变成产业主体" tabindex="-1">三、“智能体开发者”被单独写进去，意味着 Agent 已经开始从技术概念变成产业主体 <a class="header-anchor" href="#三、-智能体开发者-被单独写进去-意味着-agent-已经开始从技术概念变成产业主体" aria-label="Permalink to &quot;三、“智能体开发者”被单独写进去，意味着 Agent 已经开始从技术概念变成产业主体&quot;">​</a></h2><p>这里尤其值得关注“智能体开发者”五个字。</p><p>国务院“人工智能＋”文件已经把“智能体”列入未来大规模普及的智能产品形态，并给出了 2027 年、2030 年的应用普及目标。</p><p>现在，工信部进一步把“智能体开发者”写进创业主体培育政策。</p><p>前者解决的是：</p><p><strong>智能体会不会成为重要应用形态？</strong></p><p>后者开始回答：</p><p><strong>谁来创造这些智能体？</strong></p><p>这两个政策接起来，意义完全不同。</p><p>它意味着 Agent 正在从大模型厂商提供的一个产品功能，逐渐进入一个独立的产业生态：</p><p>有人提供模型；</p><p>有人提供算力；</p><p>有人开发 Agent；</p><p>有人提供 Agent 工具和开发框架；</p><p>有人做行业 Agent；</p><p>有人负责交付；</p><p>有人做运行、治理、安全和合规；</p><p>最终有人把这些能力部署进企业。</p><p>这也是为什么 8 月 31 日的 414 号文和 9 月 4 日的新文件必须放在一起看。</p><p>414 号文在建设“人工智能应用服务商”队伍，新文件则在扩大“人工智能创业企业”供给。</p><p>一个偏向<strong>交付体系</strong>，一个偏向<strong>创新和创业体系</strong>。</p><p>中国正在形成的不只是“大模型产业”，而是围绕人工智能应用建立一整条新的服务产业链。</p><hr><h2 id="四、这不是单纯扶持-做-ai-的企业-而是在同时建设-ai-的供给端和需求端" tabindex="-1">四、这不是单纯扶持“做 AI 的企业”，而是在同时建设 AI 的供给端和需求端 <a class="header-anchor" href="#四、这不是单纯扶持-做-ai-的企业-而是在同时建设-ai-的供给端和需求端" aria-label="Permalink to &quot;四、这不是单纯扶持“做 AI 的企业”，而是在同时建设 AI 的供给端和需求端&quot;">​</a></h2><p>文件开头有一句容易被忽略的话：</p><p>要“促进人工智能中小企业创业创新与人工智能赋能中小企业高质量发展相结合”。</p><p>这句话实际上定义了整个政策的经济结构。</p><p>它不是单向扶持。</p><p>一边是：</p><p><strong>AI 中小企业。</strong></p><p>它们需要市场、算力、数据、融资、场景。</p><p>另一边是：</p><p><strong>中国数量极其庞大的普通中小企业。</strong></p><p>它们需要人工智能降低成本、提高效率、改善研发、生产、销售和经营管理。</p><p>国家希望把两边接起来。</p><p>所以文件后来专门提出，要围绕经营管理、生产制造、研发设计等核心业务领域，培育一批“小快轻准”的人工智能产品解决方案，让“中小企业人工智能应用探索”和“人工智能中小企业创业创新”形成双向促进。</p><p>这句话非常重要。</p><p>它说明未来最大的 AI 市场之一，未必是消费者多订阅一个聊天机器人。</p><p>而可能是：</p><p><strong>数百万家中小企业开始购买大量价格不高、范围不大、但是可以直接解决经营问题的 AI 产品和数字员工。</strong></p><p>比如采购助手、销售 Agent、客户服务 Agent、研发助手、质量分析、文档处理、市场情报、财务辅助、知识管理、供应链分析等。</p><p>这也是“小快轻准”的真正市场逻辑。</p><p>大企业可能采购一个数千万元的数字化项目。</p><p>一家几十人的制造企业不会。</p><p>但是它可能愿意每个月花几千元、几万元，让几个真正能工作的 AI 系统进入自己的业务流程。</p><p>如果这种需求形成规模，就会出现一个完全不同于传统企业软件的新市场。</p><p><a href="/joinwell52/assets/figures/miit-ai-sme-support-plan/zh/03-two-sided-market.png"><img src="'+l+'" alt="人工智能中小企业与普通中小企业构成双向市场"></a></p><p><em>图 3｜AI 创业企业提供“小快轻准”产品，普通中小企业以真实业务需求反向推动产品成熟。</em></p><hr><h2 id="五、国家正在解决-ai-创业最困难的问题-不是技术-而是-第一批客户从哪里来" tabindex="-1">五、国家正在解决 AI 创业最困难的问题：不是技术，而是“第一批客户从哪里来” <a class="header-anchor" href="#五、国家正在解决-ai-创业最困难的问题-不是技术-而是-第一批客户从哪里来" aria-label="Permalink to &quot;五、国家正在解决 AI 创业最困难的问题：不是技术，而是“第一批客户从哪里来”&quot;">​</a></h2><p>中国并不缺会开发 AI 产品的人。</p><p>真正困难的是：</p><p><strong>产品做出来以后，谁让你进去试？</strong></p><p>尤其工业、医疗、材料、制造等行业，场景、数据和业务流程通常掌握在已有企业手中。</p><p>一个创业团队即使技术很好，也可能没有真实数据，没有测试环境，没有行业客户，更没有机会证明自己的产品。</p><p>因此，这份文件用了相当大的篇幅解决“场景”。</p><p>它提出通过“百场万企”、人工智能赋能新型工业化“深度行”等活动，引导链主企业开放<strong>试验验证、示范应用、规模化商用</strong>场景；同时提出遴选“人工智能创业场景合伙人”，帮助创业企业完成场景征集、需求分析、试点验证和推广应用。</p><p>注意这里出现了三个阶段：</p><p><strong>试验验证 → 示范应用 → 规模化商用。</strong></p><p>这已经不是举办一场创业比赛那么简单。</p><p>它实际上在尝试建立 AI 创业企业的市场进入通道。</p><p>过去政府扶持创业往往容易集中在“给场地”“给比赛”“给补贴”。</p><p>现在文件明确提出，孵化载体不能继续以传统办公空间租赁为主要服务，而要把<strong>算力、行业数据、应用场景</strong>纳入核心服务。</p><p>这个变化非常现实。</p><p>AI 创业公司真正需要的可能根本不是一间便宜办公室。</p><p>而是：</p><p>我有没有模型？</p><p>有没有算力？</p><p>有没有真实数据？</p><p>有没有客户愿意让我试？</p><p>有没有第一张订单？</p><p>国家政策正在逐渐围绕这些问题重新定义“孵化”。</p><p><a href="/joinwell52/assets/figures/miit-ai-sme-support-plan/zh/04-scenario-conversion.png"><img src="'+h+'" alt="从试验验证到规模化商用的场景转化路径"></a></p><p><em>图 4｜政策试图把真实场景转化为市场进入通道：试验验证、示范应用，再到规模化商用。</em></p><hr><h2 id="六、为什么文件如此强调开源-因为国家开始把开源当成-ai-创业基础设施" tabindex="-1">六、为什么文件如此强调开源？因为国家开始把开源当成 AI 创业基础设施 <a class="header-anchor" href="#六、为什么文件如此强调开源-因为国家开始把开源当成-ai-创业基础设施" aria-label="Permalink to &quot;六、为什么文件如此强调开源？因为国家开始把开源当成 AI 创业基础设施&quot;">​</a></h2><p>文件专门把“深化开源生态赋能”列为四大重点板块之一。</p><p>它不仅鼓励企业使用开源模型，而是连续部署：</p><p>支持国家级人工智能开源社区；</p><p>鼓励企业贡献模型、工具、数据集；</p><p>推广开源基础模型、开发框架、工具链和数据集；</p><p>提供模型选型、微调、性能评测和推理部署服务；</p><p>支持基于开源成果开发软件、垂类模型和行业解决方案；</p><p>探索开源成果商业转化机制。</p><p>这说明一个政策判断正在形成：</p><p><strong>中国不可能要求每一家 AI 创业公司都从基础模型重新做起。</strong></p><p>真正合理的产业结构应该是少数企业投入巨资做基础设施和基础模型，大量创业企业利用开放模型、工具和数据，在其上做工程、产品、Agent 和行业应用。</p><p>这其实与互联网和云计算时代的软件产业分层非常类似。</p><p>基础模型越成熟，上层创业门槛越低。</p><p>开源越丰富，小企业越可能快速进入市场。</p><p>所以开源在这里已经不仅是一种软件开发方式。</p><p>它开始承担一种产业公共基础设施的角色。</p><hr><h2 id="七、一个非常新的信号-github-star-开始进入政府-发现企业-的视野" tabindex="-1">七、一个非常新的信号：GitHub Star 开始进入政府“发现企业”的视野 <a class="header-anchor" href="#七、一个非常新的信号-github-star-开始进入政府-发现企业-的视野" aria-label="Permalink to &quot;七、一个非常新的信号：GitHub Star 开始进入政府“发现企业”的视野&quot;">​</a></h2><p>整份文件最后几句话，也许是最容易被低估、却最值得技术创业者认真看的内容。</p><p>文件要求：</p><p>各级中小企业主管部门积极利用人工智能和大数据分析等数字化手段，结合<strong>企业领军人才、发明专利、高被引论文、开源项目星标数等多维指标，主动识别高成长潜力企业</strong>。</p><p>这里有两个关键词。</p><p>第一个是：</p><p><strong>开源项目星标数。</strong></p><p>也就是 GitHub、AtomGit 等开源社区能够观察到的项目影响力指标，第一次如此直接地进入高成长企业识别的政策语言。</p><p>过去企业进入政府培育体系，最典型的路径是企业自己找通知、准备材料、申报、评审。</p><p>而这里出现了第二个更重要的词：</p><p><strong>主动识别。</strong></p><p>这意味着未来优质中小企业培育有可能越来越数据化。</p><p>不是只有企业向政府证明“我很好”，政府的公共服务系统也开始利用企业公开产生的数据寻找潜力企业。</p><p>专利是一种信号。</p><p>论文是一种信号。</p><p>人才是一种信号。</p><p>开源项目同样成为一种信号。</p><p>当然，这绝不意味着 GitHub Star 多就能自动成为专精特新企业，也不意味着 Star 数直接对应补贴。</p><p>它的真正意义在于：</p><p><strong>开源影响力开始获得政策层面的正式可见性。</strong></p><p>对于大量软件、开发工具、Agent、基础设施类创业项目来说，这是一个很大的变化。</p><p>因为这些企业在早期可能收入不大、员工不多、固定资产也很少。</p><p>如果仍然只用传统工业企业指标衡量，很容易看不见它们。</p><p>开源贡献、代码影响力、开发者生态恰恰可能更早地反映它们的技术价值。</p><hr><h2 id="八、这次国家给出了非常具体的三年目标" tabindex="-1">八、这次国家给出了非常具体的三年目标 <a class="header-anchor" href="#八、这次国家给出了非常具体的三年目标" aria-label="Permalink to &quot;八、这次国家给出了非常具体的三年目标&quot;">​</a></h2><p>这份文件不是只有方向。</p><p>到 2028 年，计划：</p><p>新培育科技和创新型中小企业 <strong>1 万家以上</strong>；</p><p>人工智能领域专精特新“小巨人”企业<strong>突破 2000 家</strong>；</p><p>高标准建设 <strong>10 个科技型企业孵化器</strong>；</p><p>建设 <strong>10 个国家中小企业公共服务示范平台（基地）</strong>；</p><p>新培育 <strong>10 个国家级中小企业特色产业集群</strong>。</p><p>理解 2000 家“小巨人”是什么概念，可以参照当前全国的培育规模。</p><p>工信部今年披露，“十四五”以来全国累计培育专精特新“小巨人”企业约 <strong>1.76 万家</strong>、专精特新中小企业超过 <strong>14 万家</strong>、科技和创新型中小企业超过 <strong>60 万家</strong>。</p><p>所以把人工智能单独拿出来提出“小巨人突破 2000 家”，反映的不是简单追求企业数量。</p><p>它说明人工智能正在被纳入未来优质中小企业梯度培育体系中的一个重要增长方向。</p><p>而且政策并没有希望这些企业永远保持“小创业公司”。</p><p>文件明确写的是：</p><p>创业主体 → 科技和创新型中小企业 → 专精特新中小企业 → 专精特新“小巨人” → 瞪羚与独角兽。</p><p>这实际上是一条国家希望建立的 AI 企业成长梯度。</p><p><a href="/joinwell52/assets/figures/miit-ai-sme-support-plan/zh/05-2028-targets.png"><img src="'+c+'" alt="2028年目标与人工智能企业成长梯度"></a></p><p><em>图 5｜三年数量目标与从创业主体到瞪羚、独角兽的成长梯度。</em></p><hr><h2 id="九、钱从哪里来-政策正在从-财政补贴-走向资本、算力、数据共同参与" tabindex="-1">九、钱从哪里来？政策正在从“财政补贴”走向资本、算力、数据共同参与 <a class="header-anchor" href="#九、钱从哪里来-政策正在从-财政补贴-走向资本、算力、数据共同参与" aria-label="Permalink to &quot;九、钱从哪里来？政策正在从“财政补贴”走向资本、算力、数据共同参与&quot;">​</a></h2><p>另一个值得注意的变化，是支持方式越来越不像传统的单一财政补贴。</p><p>文件提出发挥：</p><p>国家中小企业发展基金、</p><p>国家人工智能产业投资基金、</p><p>国家集成电路产业投资基金</p><p>的引导作用，并带动社会资本建立覆盖种子期、初创期和成长期的早期风险投资和创业投资体系。</p><p>更有意思的是后面：</p><p>探索<strong>算力入股、数据入股、投孵联动</strong>等支持方式。</p><p>为什么会出现这种设计？</p><p>因为 AI 企业和传统企业不一样。</p><p>很多创业项目最大的成本并不是土地和厂房。</p><p>而可能是 Token、GPU、数据、模型调用、测试环境和行业场景。</p><p>于是政策支持的“生产要素”也必须改变。</p><p>传统产业政策可能给土地、设备、厂房。</p><p>AI 创业时代，对一家初创公司真正有价值的政府支持，也许是：</p><p>50 万元算力；</p><p>一个高质量行业数据集；</p><p>一家大型企业提供六个月真实试运行场景；</p><p>以及一笔种子轮资金。</p><p>这种政策工具的变化，本身就是产业结构变化的结果。</p><hr><h2 id="十、为什么国家现在要大规模扶持-ai-中小企业" tabindex="-1">十、为什么国家现在要大规模扶持 AI 中小企业？ <a class="header-anchor" href="#十、为什么国家现在要大规模扶持-ai-中小企业" aria-label="Permalink to &quot;十、为什么国家现在要大规模扶持 AI 中小企业？&quot;">​</a></h2><p>还有一个更宏观的问题：</p><p>既然大型科技公司已经在投入人工智能，为什么国家还要专门出台一个政策，大规模培育 AI 中小企业？</p><p>因为大模型解决不了所有行业的最后一公里。</p><p>中国拥有全球最完整的产业体系，同时拥有数量极其庞大的中小企业。</p><p>真正把人工智能送进这些企业，需要大量非常细的知识：</p><p>一家汽车零部件企业怎样质检；</p><p>一家化工企业怎样采购；</p><p>一家外贸公司怎样管理客户；</p><p>一家机械厂怎样报价；</p><p>一家物流企业怎样排班；</p><p>一家材料企业怎样做研发文献分析。</p><p>这些问题不可能全部由几家基础模型公司完成。</p><p>它们需要成千上万家公司，在无数细分行业里不断试验。</p><p>这就是中小企业的价值。</p><p>它们承担的不是基础模型规模竞争，而是<strong>场景创新和商业模式创新</strong>。</p><p>所以国家真正希望形成的结构可能是：</p><p>基础模型企业提供底座；</p><p>算力和数据基础设施提供公共资源；</p><p>大量人工智能创业企业创造产品；</p><p>人工智能应用服务商完成交付；</p><p>数百万中小企业成为应用市场。</p><p>这才是一套真正能够支撑“人工智能＋”大规模落地的产业结构。</p><hr><h2 id="十一、对-agent-创业者来说-机会可能不在-再做一个聊天机器人" tabindex="-1">十一、对 Agent 创业者来说，机会可能不在“再做一个聊天机器人” <a class="header-anchor" href="#十一、对-agent-创业者来说-机会可能不在-再做一个聊天机器人" aria-label="Permalink to &quot;十一、对 Agent 创业者来说，机会可能不在“再做一个聊天机器人”&quot;">​</a></h2><p>如果站在创业者角度看，这份文件同样提供了一个很重要的判断。</p><p>未来真正受到产业政策鼓励的方向，越来越不像“做一个 AI Demo”。</p><p>而是：</p><p><strong>能够进入真实产业流程、能够持续工作、能够部署、能够交付、能够运营、能够治理的 AI 产品。</strong></p><p>这就是为什么文件同时谈：</p><p>智能体；</p><p>“小快轻准”产品；</p><p>行业应用；</p><p>服务商；</p><p>数据；</p><p>算力；</p><p>安全；</p><p>合规；</p><p>知识产权；</p><p>场景；</p><p>开源；</p><p>融资。</p><p>它们实际上拼成的是一张完整的 AI 生产系统。</p><p>对于我们正在研究的 CodeFlowMu、FCoP 这一类 Agent 基础设施，也可以从这个政策变化中看到一个非常明确的市场方向。</p><p>如果未来企业真正开始部署数字员工，那么问题很快就会从：</p><p><strong>“模型聪不聪明？”</strong></p><p>转变成：</p><p><strong>“这个数字员工怎样长期运行？”</strong></p><p>它有没有身份？</p><p>有没有职责？</p><p>可以调用什么工具？</p><p>谁授权？</p><p>出了错误怎样恢复？</p><p>多 Agent 怎样协作？</p><p>过程如何审计？</p><p>结果由谁验收？</p><p>企业的数据和权限怎样保护？</p><p>这些并不是基础模型本身能够自动解决的问题。</p><p>也就是说，大模型越成熟，Agent 真正进入企业以后，<strong>Agent 运行、协作、治理、审计和安全基础设施的重要性反而会上升。</strong></p><p>但必须强调，现阶段这仍然只是对政策方向和产业结构的判断，并不意味着某一个具体项目已经被纳入某项国家扶持计划。真正的项目申报条件、评价标准和地方承接政策，还需要等待后续各地实施细则。</p><hr><h2 id="十二、最值得关注的不是一笔补贴-而是一个新产业正在被组织起来" tabindex="-1">十二、最值得关注的不是一笔补贴，而是一个新产业正在被组织起来 <a class="header-anchor" href="#十二、最值得关注的不是一笔补贴-而是一个新产业正在被组织起来" aria-label="Permalink to &quot;十二、最值得关注的不是一笔补贴，而是一个新产业正在被组织起来&quot;">​</a></h2><p>读完整份文件后，一个最容易出现的误区是：</p><p>“国家准备拿多少钱补贴 AI 创业？”</p><p>但这可能不是最重要的问题。</p><p>因为这份计划本身并不是一个具体资金申报通知，也没有给出“每家公司补贴多少万元”。</p><p>它做的事情其实更大：</p><p><strong>国家开始组织一个人工智能创业生态。</strong></p><p>算力从哪里来；</p><p>数据怎么开放；</p><p>场景谁来提供；</p><p>创业主体是谁；</p><p>智能体开发者怎样商业化；</p><p>开源项目怎样转化；</p><p>服务商谁来交付；</p><p>资本怎样进入；</p><p>安全合规怎样解决；</p><p>政府又怎样发现那些尚未出名、却可能高速成长的企业。</p><p>这些问题现在第一次被比较系统地装进同一个三年计划里。</p><p>这也解释了文件开头为什么用了一个很特别的比喻：</p><p>要营造**“热带雨林”式创业创新生态**。</p><p>热带雨林不是种一棵参天大树。</p><p>它需要乔木、灌木、藤蔓、微生物和无数小型生命共同存在。</p><p>放到人工智能产业也是一样。</p><p>中国已经拥有大型模型企业、互联网平台、通信运营商和算力基础设施。</p><p>接下来需要大量出现的，很可能恰恰是那些很小、很专业、很靠近行业现场的公司。</p><p>其中一些甚至可能只有几个人。</p><p>甚至一个人。</p><p>但那个人背后，可能运行着十几个 Agent。</p><hr><h2 id="结语-从-大模型竞赛-进入-百万企业应用-的阶段" tabindex="-1">结语：从“大模型竞赛”，进入“百万企业应用”的阶段 <a class="header-anchor" href="#结语-从-大模型竞赛-进入-百万企业应用-的阶段" aria-label="Permalink to &quot;结语：从“大模型竞赛”，进入“百万企业应用”的阶段&quot;">​</a></h2><p>过去几年，全世界观察人工智能产业，最容易盯着几个指标：</p><p>谁的模型参数更多？</p><p>谁的 Benchmark 更高？</p><p>谁融资更多？</p><p>谁拥有更多 GPU？</p><p>这些仍然重要。</p><p>但国家最新一轮政策透露出的方向正在变化。</p><p>2025 年国务院确定“人工智能＋”。</p><p>2026 年“十五五”规划把人工智能进一步放进经济社会数智化发展的主干。</p><p>随后，算力、开源、“小快轻准”产品、应用服务商、智能体开发者、AI 创业企业开始被一项一项组织起来。</p><p>这意味着中国人工智能产业竞争正在进入第二阶段：</p><p><strong>从“谁能把模型做出来”，逐渐进入“谁能让人工智能真正进入千行百业”。</strong></p><p>而在这个阶段，真正决定产业规模的可能不再只是几十家大型模型公司。</p><p>还有数千家人工智能应用服务商；</p><p>上万家人工智能创业企业；</p><p>数十万开发者；</p><p>以及未来使用这些产品的数百万家中小企业。</p><p>工信部这份最新文件真正值得重视的地方，就在这里。</p><p>它不是在告诉市场：</p><p><strong>“人工智能很重要。”</strong></p><p>这件事早已经没有争议。</p><p>它开始回答一个更现实的问题：</p><p><strong>国家准备怎样让一大批普通创业者、开发者和中小企业真正进入人工智能产业。</strong></p><p>而“一人公司”“超级个体”“智能原生企业”“智能体开发者”“开源项目星标数”这些以前很难出现在产业政策里的词，现在已经正式写进国家部门文件。</p><p>这或许比任何一笔单独的补贴，都更能说明变化已经发生。</p><hr><h2 id="主要资料与口径说明" tabindex="-1">主要资料与口径说明 <a class="header-anchor" href="#主要资料与口径说明" aria-label="Permalink to &quot;主要资料与口径说明&quot;">​</a></h2><ul><li><a href="https://www.miit.gov.cn/jgsj/qyj/wjfb/art/2026/art_86c400b4473849818629663a94a6d44b.html" target="_blank" rel="noreferrer">工业和信息化部办公厅关于印发《人工智能中小企业创业支持计划（2026—2028年）》的通知</a></li><li><a href="https://www.miit.gov.cn/jgsj/txs/wjfb/art/2026/art_e5c990d4ec924dbc9da5818da97940ac.html" target="_blank" rel="noreferrer">工业和信息化部办公厅关于开展普惠算力赋能中小企业发展专项行动的通知</a></li><li><a href="https://www.miit.gov.cn/jgsj/qyj/gzdt/art/2026/art_7d898f9702124499aa651da5c9c4d66f.html" target="_blank" rel="noreferrer">工业和信息化部等十部门《促进中小企业发展“十五五”规划》解读</a></li></ul><p>文中的产业影响和阶段判断属于基于公开政策文本的分析，不等同于具体项目申报承诺；实际支持条件、执行时间和地方承接方式，应以后续正式通知为准。</p>',329))])}const k=a(m,[["render",u]]);export{q as __pageData,k as default};
